export class GraphRAG {
  constructor() {
    this.graph = new Map(); // Use a Map to store entity relationships
  }

  addEntity(entity, relationships) {
    // Add or update an entity and its relationships
    this.graph.set(entity, relationships);
  }

  queryEntity(entity) {
    // Retrieve relationships for a given entity
    return this.graph.get(entity) || [];
  }

  updateEntity(entity, newRelationships) {
    // Update existing entity relationships
    if (this.graph.has(entity)) {
      this.graph.set(entity, newRelationships);
    }
  }

  getAllEntities() {
    // Return all entities in the graph
    return Array.from(this.graph.keys());
  }
}
